fun cookAgain(cmd: CookAgain): Outcome {
    val recipe = recipes.find(cmd.recipeId)                    // 1. load
        ?: return Outcome.NotFound(cmd.recipeId)
    if (!recipe.cookedBefore)                                  // 2. check the rule
        return Outcome.NeverCooked(recipe.id)
    val orderId = shop.order(recipe.ingredients, cmd.servings) // 3. act
        ?: return Outcome.Refused(recipe.id)
    return Outcome.Ordered(orderId)                            // 4. the happy path, last
}

